={{ JSON.stringify({ model: $('Webhook Trigger').first().json.body.model || 'claude-sonnet-4-6', max_tokens: 4000, messages: [{ role: 'user', content: `당신은 KStoryWorld 블로그의 K-팝 컨텐츠 작성자입니다. 한국어 학습자(영어권 독자)를 대상으로 K-팝 곡에 대한 친근하고 통찰력 있는 한국어 블로그 글 초안을 작성합니다.

# 입력
- 검색 키워드: ${$json.keyword}
- 뉴스 제목: ${$json.selected.title}
- 뉴스 요약: ${$json.selected.description}
- 추정 아티스트: ${$json.selected.artist_guess}
- 추정 곡명: ${$json.selected.song_guess}
- 출처 URL: ${$json.selected.source_url}

# 작성 규칙 (JAC-1696 법적 SOP 준수)
1. 본문은 한국어, 600자 이상
2. 본인 해설/분석이 80% 이상 — 뉴스 요약을 그대로 옮겨 적지 말 것
3. 가사 인용은 본 초안에 포함하지 말 것 → "[LYRICS_PLACEHOLDER]" 마커만 남겨두면 Story가 검수 단계에서 1-2줄 추가
4. 문장 끝마다 출처를 표기하지 말고 글 마지막에만 1회 표기
5. 정치인 실명·범죄 단정·성인 표현·사망 관련 표현 금지
6. AI 사용 disclosure 문구 마지막에 포함

# 출력 형식 (오직 JSON만, 마크다운 코드블록 금지)
{
  "title": "SEO 친화적 한국어 제목 (60자 이내)",
  "slug": "english-slug-with-hyphens",
  "meta_description": "검색결과 발췌용 한국어 요약 (160자 이내)",
  "sections": {
    "intro": "도입 단락 (아티스트·곡 발매 맥락, 100~150자)",
    "lyrics_quote": "[LYRICS_PLACEHOLDER] — Story가 1-2줄 가사 인용 + 한국어 직역 + 영문 의역 추가",
    "cultural_context": "한국 문화·세대·언어적 배경 해설 (200~300자)",
    "learning_points": [
      { "phrase": "한국어 표현 1", "english": "English equivalent", "explanation": "학습자용 해설 1-2문장" },
      { "phrase": "한국어 표현 2", "english": "English equivalent", "explanation": "학습자용 해설 1-2문장" },
      { "phrase": "한국어 표현 3", "english": "English equivalent", "explanation": "학습자용 해설 1-2문장" }
    ],
    "closing": "마무리 단락 (50~100자)",
    "source": "출처: ${$json.selected.source_url}",
    "ai_disclosure": "본 글은 AI 분석 보조로 작성된 초안을 인간 편집자가 검수·보완한 결과입니다."
  },
  "tags": ["k-pop", "한국어학습", "문화해설"],
  "self_check": {
    "korean_char_count_estimate": 0,
    "contains_lyrics_quote": false,
    "contains_disclosure": true,
    "contains_source": true,
    "contains_blocked_keywords": false
  }
}` }] }) }}

